CREATE OR REPLACE VIEW `v_reporte_actividades_diario` AS select `a`.`id` AS `actividad_id`,`a`.`fecha` AS `fecha`,`a`.`campo` AS `campo`,`a`.`codigo_labor` AS `codigo_labor`,`a`.`nombre_labor` AS `nombre_labor`,`a`.`unidades` AS `unidades`,`a`.`recojos` AS `recojos`,count(distinct `am`.`id`) AS `total_metodos`,count(distinct `pdh`.`plan_reg_dia_id`) AS `total_planilla`,count(distinct `cdh`.`registro_diario_id`) AS `total_cuadrilla` from (((`actividades` `a` left join `actividad_metodos` `am` on((`am`.`actividad_id` = `a`.`id`))) left join `plan_detalles_horas` `pdh` on(((`pdh`.`campo_nombre` = `a`.`campo`) and (`pdh`.`codigo_labor` = `a`.`codigo_labor`) and exists(select 1 from `plan_registros_diarios` `prd` where ((`prd`.`id` = `pdh`.`plan_reg_dia_id`) and (`prd`.`fecha` = `a`.`fecha`)))))) left join `cuad_detalles_horas` `cdh` on(((`cdh`.`campo_nombre` = `a`.`campo`) and (`cdh`.`codigo_labor` = `a`.`codigo_labor`) and exists(select 1 from `cuad_registros_diarios` `crd` where ((`crd`.`id` = `cdh`.`registro_diario_id`) and (`crd`.`fecha` = `a`.`fecha`)))))) group by `a`.`id`,`a`.`fecha`,`a`.`campo`,`a`.`codigo_labor`,`a`.`nombre_labor`,`a`.`unidades`,`a`.`recojos`;
